'use strict';
const KEY='alfaisal-review-studio-v1', $=s=>document.querySelector(s), esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Riyadh',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const add=(d,n)=>{let v=new Date(d+'T12:00:00Z');v.setUTCDate(v.getUTCDate()+n);return v.toISOString().slice(0,10)}, fmt=d=>d?new Date(d+'T12:00:00Z').toLocaleDateString('en-GB',{day:'numeric',month:'short',timeZone:'Asia/Riyadh'}):'Unscheduled', stamp=d=>new Date(d).toLocaleString('en-GB',{timeZone:'Asia/Riyadh',day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'});
let saved={},view='dashboard',tab='all',editing=null, filters={q:'',course:'all',status:'all',due:'all'},storageOK=true;
try{saved=JSON.parse(localStorage.getItem(KEY)||'{}');if(!saved||typeof saved!=='object'||Array.isArray(saved))saved={}}catch{storageOK=false}
let state=saved.records||{},settings={budget:180,catchup:true,...saved.settings},day=today();$('#day').value=day;
const rec=x=>state[x.id]||{}, dates=x=>rec(x).dates||x.dates, title=x=>rec(x).title||x.title, done=(x,p)=>rec(x).done?.[p]||null, completed=x=>[0,1,2].filter(p=>done(x,p)).length;
function persist(){try{localStorage.setItem(KEY,JSON.stringify({version:2,records:state,settings}));$('#storageStatus').textContent='';storageOK=true;scheduleSync()}catch{storageOK=false;$('#storageStatus').textContent='Saving unavailable. Export a backup before closing.';if(typeof paintSyncSummary==='function')paintSyncSummary('Device saving unavailable')}}
let toastTimer=null;
function toast(t,undo=null){clearTimeout(toastTimer);const el=$('#toast');el.textContent=t;if(undo){const b=document.createElement('button');b.type='button';b.textContent='Undo';b.className='toast-undo';b.onclick=()=>{undo();el.classList.remove('show')};el.appendChild(b)}el.classList.add('show');toastTimer=setTimeout(()=>el.classList.remove('show'),undo?8000:3000)}
function tasks(items=DATA.items){return items.flatMap(x=>[0,1,2].map(p=>({x,p,date:dates(x)[p],done:done(x,p)})))}
function baseRow(x){return `<article class="lecture ${x.course==='MOL'?'mol':''}"><div class="lecture-top"><span class="code">${esc(x.code)}</span><div class="lecture-info"><h3>${esc(title(x))}</h3><div class="meta">${esc(x.group)} <br>${x.course==='CVP'?'Preset PDF plan':'Suggested editable review plan'}${rec(x).dates?' · Dates customized':''}${rec(x).confidence?' · Confidence '+rec(x).confidence+'/5':''}</div></div><button class="edit" data-edit="${x.id}" aria-label="Edit ${esc(x.code)}">Edit ↗</button></div><div class="passes">${[0,1,2].map(p=>`<label class="pass ${done(x,p)?'done':dates(x)[p]<day?'late':''}"><input type="checkbox" data-id="${x.id}" data-pass="${p}" ${done(x,p)?'checked':''} aria-label="${esc(x.code)} ${p+1}${['st','nd','rd'][p]} review completed"><strong>${p+1}${['st','nd','rd'][p]} review</strong><small>${done(x,p)?'Done '+esc(stamp(done(x,p))):'Planned '+fmt(dates(x)[p])}</small></label>`).join('')}</div>${rec(x).notes?`<div class="note-preview">${esc(rec(x).notes)}</div>`:''}</article>`}
function progress(course){let a=DATA.items.filter(x=>x.course===course),t=tasks(a),n=t.filter(x=>x.done).length;return `<div class="progress-row"><div class="section-head"><strong>${course} ${course==='MOL'?'114':'112'}</strong><span>${Math.round(n/t.length*100)}%</span></div><div class="bar ${course==='MOL'?'mol':''}"><i style="width:${n/t.length*100}%"></i></div><small>${n} / ${t.length} reviews complete · ${a.filter(x=>completed(x)===3).length} / ${a.length} items fully reviewed</small></div>`}
function intro(label,heading,sub){return `<div class="intro"><div><div class="eyebrow muted">${label}</div><h1>${heading}</h1><p class="muted">${sub}</p></div><span class="pill" data-profile-group>${esc(window.reviewGroupLabel?.()||'Made by Hatem')}</span></div>`}
function baseFiltered(){return DATA.items.filter(x=>{let t=tasks([x]),c=completed(x);return (filters.course==='all'||x.course===filters.course||filters.course==='midterm'&&x.midterm)&&(!filters.q||(title(x)+' '+x.code+' '+x.group+' '+(rec(x).notes||'')).toLowerCase().includes(filters.q.toLowerCase()))&&(filters.status==='all'||filters.status==='notstarted'&&c===0||filters.status==='progress'&&c>0&&c<3||filters.status==='done'&&c===3||filters.status==='weak'&&((+rec(x).confidence>0&&+rec(x).confidence<=2)||rec(x).notes))&&(filters.due==='all'||t.some(t=>!t.done&&(filters.due==='today'?t.date===day:filters.due==='overdue'?t.date<day:t.date>=day&&t.date<=add(day,6))))})}
function lectures(){return intro('YOUR COMPLETE REVIEW LIBRARY',view==='weakness'?'Turn weak spots into strengths.':'One lecture. Three independent passes.',view==='weakness'?'Difficult topics, confidence rated 1–2, notes, or recent MCQs below 70%. Results feed your daily priorities.':'CVP preset dates and suggested MOL reviews, together in one place.')+`<section class="panel"><div class="filters"><input id="search" type="search" placeholder="Search lectures, topics or notes…" value="${esc(filters.q)}" aria-label="Search lectures"><select id="course" aria-label="Filter by course">${[['all','All courses'],['MOL','MOL 114'],['CVP','CVP 112']].map(([v,l])=>`<option value="${v}" ${filters.course===v?'selected':''}>${l}</option>`).join('')}</select><select id="status" aria-label="Filter by status">${[['all','Any status'],['notstarted','Not started'],['progress','In progress'],['done','All 3 complete'],['weak','Weak areas / notes']].map(([v,l])=>`<option value="${v}" ${filters.status===v?'selected':''}>${l}</option>`).join('')}</select><select id="due" aria-label="Filter by due date">${[['all','Any due date'],['today','Due selected day'],['overdue','Overdue'],['week','Next 7 days']].map(([v,l])=>`<option value="${v}" ${filters.due===v?'selected':''}>${l}</option>`).join('')}</select></div><div id="results"></div></section>`}
function results(){let a=filtered();$('#results').innerHTML=`<p class="section-sub">${a.length} items · ${tasks(a).filter(t=>!t.done).length} unfinished passes</p>`+(a.length?a.map(row).join(''):'<div class="empty">No lectures match these filters.</div>')}
function calendar(){let start=add(day,-new Date(day+'T12:00:00Z').getUTCDay()),ev=DATA.events.filter(e=>e.date===day),a=DATA.items.filter(x=>dates(x).includes(day));return intro('STUDY & CAMPUS, SIDE BY SIDE','Your daily schedule.','Review due dates and documented teaching events remain distinct.')+`<div class="calendar-strip">${Array.from({length:7},(_,n)=>{let d=add(start,n);return `<button data-day="${d}" class="${day===d?'selected':''}">${['SUN','MON','TUE','WED','THU','FRI','SAT'][n]}<strong>${+d.slice(8)}</strong><small>${tasks().filter(t=>t.date===d&&!t.done).length} reviews due</small></button>`}).join('')}</div><div class="section-head"><button data-day="${add(day,-7)}">← Previous week</button><span>${fmt(start)} – ${fmt(add(start,6))}</span><button data-day="${add(day,7)}">Next week →</button></div><div class="grid"><section class="panel"><h2>Planned reviews · ${fmt(day)}</h2><p class="muted" style="font-size:11px">${tasks().filter(t=>t.date===day&&!t.done).length} unfinished passes. Other pass dates are shown for context.</p>${a.length?a.map(row).join(''):'<div class="empty">No reviews planned on this day.</div>'}</section><section class="panel"><h2>Course timetable & events</h2><p class="section-sub" style="margin-top:12px">Male-I lectures and M1-A labs. Exact group ranges override section defaults.</p>${ev.length?ev.map(e=>`<div class="event"><span class="pill">${esc(e.type)}</span><p><strong>${esc(e.title)}</strong></p>${e.slot?`<p>Source slot: ${esc(e.slot)}</p>`:''}${e.detail?`<p>${esc(e.detail)}</p>`:''}<small>${esc(e.source)}${e.cell?' · Sheet1!'+e.cell:''}</small></div>`).join(''):'<p class="muted">No documented events in the supplied files for this day.</p>'}<p class="notice">Timetable slot labels are reproduced as printed, not inferred event durations. Shared merged cells are included. Verify updated rooms and attendance details on Moodle.</p></section></div>`}
function methods(){return intro('GIVE EACH PASS A PURPOSE','Study. Recall. Consolidate.','The CVP PDF’s three-pass methods are preserved below. You can use them for MOL too.')+`<div class="threecol">${[['01','First study','Seniors video + slides + MCQs','Build your understanding. Use the slides as the source of truth and record the mechanisms or diagrams that need another look.'],['02','Second study','Written recall + MCQs','Close the slides and write what you remember. Check the gaps, then work through questions and add errors to your notes.'],['03','Third study','Rapid recall + mixed MCQs','Recall the core facts and mechanisms quickly. Mix topics and return to weak areas before you mark the pass done.']].map(([n,t,m,p])=>`<section class="method"><strong>${n}</strong><h2>${t}</h2><p><b>${m}</b></p><p class="muted">${p}</p></section>`).join('')}</div><section class="panel" style="margin-top:20px"><h2>A useful confidence check</h2><p class="muted">Rate each lecture from 1 (needs work) to 5 (exam ready) in Edit. Notes and ratings 1–2 appear in Weak areas. Confidence never completes a pass.</p><p>Before the MOL midterm: cover all of MOL 1–13. The guide does not give a per-lecture MCQ allocation. MOL 14–19 belong to TBL 2 and are outside midterm coverage.</p></section>`}
function sources(){return intro('FIVE FILES, ONE CLEAR PLAN','Know where each date comes from.','Original source dates are retained separately from your personal edits.')+`<section class="panel"><h2>Source register</h2><ol class="sources-list">${DATA.sources.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><p>The CVP PDF provides all 51 scheduled items and 153 review dates, October 25–November 14. Its closing plan continues through November 18. It is a study plan; teaching dates come from the XLSX.</p><p>The CVP syllabus provides objectives and assessment weights: TBL/PBL 5%, final MCQs 65%, SAQs 15%, OSPE 15%; no midterm. The timetable lists the final on November 18 and OSPE on November 19.</p><p>The MOL syllabus provides lecture objectives and practical coverage. The lecture/TBL/assessment guide provides lecture date ranges, TBL grouping, and exam coverage. Guide wording is retained for lecture titles; some syllabus titles differ slightly.</p><div class="notice">All MOL review due dates are suggestions generated for this tracker. October 25–28 is an intensive midterm catch-up plan. Later reviews are suggested after the documented lecture date, with 2- and 5-day follow-ups. Review Sessions I and II are included as items. No progress is pre-completed.</div></section><div class="threecol"><section class="panel"><h3>MOL midterm</h3><p>Thursday, 29 October 2026<br>50 MCQs · MOL 1–13<br>20% of course grade</p><p class="muted">No per-lecture question allocation is supplied. The timetable prints an 8:00 slot; the dashboard does not infer exam duration.</p></section><section class="panel"><h3>TBL grouping</h3><p>TBL 1 · MOL 1–7 · Sep 22<br>TBL 2 · MOL 14–19 · Nov 3<br>TBL 3 · MOL 20–24 · Nov 24</p><p class="muted">Guide/syllabus TBL times: 08:00–10:00. MOL 8–13 and 25–28 are outside TBL groups.</p></section><section class="panel"><h3>MOL final</h3><p>20 December 2026<br>90 MCQs + 5 SAQs</p><p class="muted">MCQs: all lectures + laboratory material. SAQs: all lectures. Labs: safety/instruments and DNA isolation/quantitation. Lab review dates are not supplied or invented.</p></section></div><section class="panel"><h2>Timetable interpretation</h2><p>Male-I column is used for lectures. M1-A anatomy lab slots are included; M1-B entries and physiology groups 1.1–1.3 are excluded. The November 9 physiology session explicitly says M1A 1.4–1.6 and is included. Shared sessions are read from horizontally merged cells.</p><p class="muted">The XLSX has repeated formatting far beyond its actual 25-column timetable. The parser uses the real weekly grids. MOL group-specific lab allocations not explicitly matching Group 1.6 are not assigned. Timetable row labels are displayed as source slots rather than inferred attendance durations.</p><details><summary>CVP syllabus content and objectives</summary><div class="syllabus">${DATA.cvpSyllabus.map(r=>`<p>${esc([...new Set(r)].join(' · '))}</p>`).join('')}</div></details></section><section class="panel"><h2>Your data</h2><p>Progress, MCQ results, saved study sessions, notes, confidence, materials and personal dates are saved on this device and synced privately to your signed-in account when online. Use the same ChatGPT account on each device. The cloud status shows whether saving succeeded. Conflicting device copies require your choice before overwriting. Export a JSON backup for an additional copy. Running timers and imported question banks stay on the device. Import validates the backup before replacing saved progress. Original CVP dates remain available in every Edit dialog.</p></section>`}
function render(){if(document.documentElement.dataset.boot==='loading'&&!window.reviewBootRender)return;if(typeof applyTheme==='function')applyTheme();if(typeof paintProfile==='function')paintProfile();document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#content').innerHTML=({dashboard,lectures,weakness:lectures,calendar,methods,sources,planner,practice,learning:()=>typeof learning==='function'?learning():'Loading lessons…',library:()=>typeof library==='function'?library():'Loading library…',anki:()=>typeof ankiPage==='function'?ankiPage():'Loading decks…',studyhub:()=>typeof studyHub==='function'?studyHub():'Loading study tools…'}[view])();if(view==='lectures'||view==='weakness')results();}
function go(v){view=v;if(v==='weakness')filters.status='weak';else if(v==='lectures'&&filters.status==='weak')filters.status='all';history.pushState(null,'','#'+v);render()}
function baseOpenEdit(id){editing=DATA.items.find(x=>x.id===id);let x=editing;$('#editTitle').textContent=x.code+' · Review details';$('#editSource').textContent=x.source+' · '+(x.course==='CVP'?'Preset PDF dates retained below.':'All review due dates are suggested and editable.');$('#titleInput').value=title(x);$('#dateFields').innerHTML=[0,1,2].map(p=>`<label>${p+1}${['st','nd','rd'][p]} review<input type="date" id="date${p}" required value="${esc(dates(x)[p])}"><small>Original ${x.course==='CVP'?'PDF':'suggested'}: ${fmt(x.dates[p])}</small></label>`).join('');$('#confidence').value=rec(x).confidence||0;$('#notes').value=rec(x).notes||'';$('#objectives').textContent=(x.lectureDates?'Documented lecture date(s): '+x.lectureDates+'. ':'')+(x.objectives||x.group+'. See Sources & coverage for full CVP syllabus objectives.');$('#editor').showModal()}
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.dataset.view)go(b.dataset.view);if(b.hasAttribute('data-midterm')){filters={q:'',course:'midterm',status:'all',due:'all'};go('lectures')}if(b.hasAttribute('data-cvp')){filters={q:'',course:'CVP',status:'all',due:'all'};go('lectures')}if(b.dataset.tab){tab=b.dataset.tab;render()}if(b.dataset.edit)openEdit(b.dataset.edit);if(b.dataset.day){day=b.dataset.day;$('#day').value=day;render()}});
document.addEventListener('change',e=>{let t=e.target;if(t.matches('[data-pass]')){let id=t.dataset.id,p=+t.dataset.pass,previous=state[id]?.done?.[p]??null,checked=t.checked;state[id]={...state[id],done:{...state[id]?.done,[p]:checked?new Date().toISOString():null}};persist();render();toast(checked?'Review completed · timestamp saved':'Review completion cleared',()=>{state[id]={...state[id],done:{...state[id]?.done,[p]:previous}};persist();render()})}if(['course','status','due'].includes(t.id)){filters[t.id]=t.value;results()}});
document.addEventListener('input',e=>{if(e.target.id==='search'){filters.q=e.target.value;results()}});
$('#day').onchange=e=>{if(e.target.value){day=e.target.value;render()}};$('#today').onclick=()=>{day=today();$('#day').value=day;render()};$('#close').onclick=()=>$('#editor').close();$('#restore').onclick=()=>{editing.dates.forEach((d,p)=>$('#date'+p).value=d);toast('Preset dates restored in editor. Save to apply.')};$('#editform').onsubmit=e=>{e.preventDefault();state[editing.id]={...rec(editing),title:$('#titleInput').value.trim()||editing.title,dates:[0,1,2].map(p=>$('#date'+p).value),confidence:+$('#confidence').value,notes:$('#notes').value};persist();$('#editor').close();render();toast('Lecture updated')};
$('#export').onclick=()=>{let blob=new Blob([JSON.stringify({app:'alfaisal-review-studio',version:2,exportedAt:new Date().toISOString(),records:state,settings},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='review-studio-backup-'+today()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);toast('Backup exported')};$('#import').onclick=()=>$('#file').click();
function validateBackup(o){StudyVault.valid(o?.extras);if(o?.app!=='alfaisal-review-studio'||![1,2].includes(o.version)||!o.records||Array.isArray(o.records)||typeof o.records!=='object')throw Error('This is not a Review Studio backup.');let clean={};for(let [id,r] of Object.entries(o.records)){if(!DATA.items.some(x=>x.id===id))throw Error('Unknown lecture in backup.');if(!r||typeof r!=='object'||Array.isArray(r))throw Error('Invalid lecture record.');let c={};if(r.title!==undefined){if(typeof r.title!=='string'||r.title.length>300)throw Error('Invalid title.');c.title=r.title}if(r.notes!==undefined){if(typeof r.notes!=='string'||r.notes.length>100000)throw Error('Invalid notes.');c.notes=r.notes}if(r.confidence!==undefined){if(!Number.isInteger(r.confidence)||r.confidence<0||r.confidence>5)throw Error('Invalid confidence.');c.confidence=r.confidence}if(r.dates!==undefined){if(!Array.isArray(r.dates)||r.dates.length!==3||r.dates.some(d=>typeof d!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(d)||!Number.isFinite(Date.parse(d))||new Date(d).toISOString().slice(0,10)!==d))throw Error('Invalid review dates.');c.dates=r.dates}if(r.done!==undefined){if(!r.done||typeof r.done!=='object'||Array.isArray(r.done))throw Error('Invalid completion records.');c.done={};for(let [p,t] of Object.entries(r.done)){if(!['0','1','2'].includes(p)||t!==null&&(typeof t!=='string'||!Number.isFinite(Date.parse(t))))throw Error('Invalid completion timestamp.');c.done[p]=t}}validateExtras(r,c);clean[id]=c}return clean}
$('#file').onchange=async e=>{try{let f=e.target.files[0];if(!f)return;if(f.size>3000000)throw Error('Backup exceeds 3 MB.');let clean=validateBackup(JSON.parse(await f.text()));if(!confirm('Replace this browser’s saved progress with this backup? Export first if you need to keep your current progress.'))return;state=clean;settings=cleanSettings(JSON.parse(await f.text()).settings);persist();render();toast('Backup imported')}catch(err){alert('Import failed: '+err.message)}finally{e.target.value=''}};
window.addEventListener('hashchange',()=>{let v=location.hash.slice(1);if(['dashboard','lectures','calendar','weakness','methods','sources','planner','practice','learning','library','anki','studyhub'].includes(v)&&view!==v){view=v;if(v==='weakness')filters.status='weak';render()}});window.addEventListener('storage',e=>{if(e.key===KEY)toast('Progress changed in another tab. Reload to use the latest copy.')});if(['dashboard','lectures','calendar','weakness','methods','sources','planner','practice','learning','library','anki','studyhub'].includes(location.hash.slice(1)))view=location.hash.slice(1);if(view==='weakness')filters.status='weak';/* Initial render follows enhancements. */if(!storageOK)$('#storageStatus').textContent='Storage unavailable. Export before closing.';
function fullDate(d){return new Date(d+'T12:00:00Z').toLocaleDateString('en-GB',{timeZone:'Asia/Riyadh',weekday:'long',day:'numeric',month:'long',year:'numeric'})}
function cleanSettings(s){const names=s?.examNames&&typeof s.examNames==='object'&&!Array.isArray(s.examNames)?Object.fromEntries(Object.entries(s.examNames).filter(([k,v])=>/^[a-z0-9][a-z0-9-]{0,119}$/i.test(k)&&typeof v==='string'&&v.trim()&&v.length<=100).slice(0,64).map(([k,v])=>[k,v.trim()])):{},colors=s?.calendarColors&&typeof s.calendarColors==='object'&&!Array.isArray(s.calendarColors)?Object.fromEntries(Object.entries(s.calendarColors).filter(([k,v])=>['anatomy','physiology','mol','lab','assessment','break','other','english'].includes(k)&&/^#[0-9a-f]{6}$/i.test(String(v)))):{};return {studentGroup:['M1','M2','F1','F2'].includes(s?.studentGroup)?s.studentGroup:'',studentSection:['A','B'].includes(s?.studentSection)?s.studentSection:'',groupConfigured:s?.groupConfigured===true,profileName:typeof s?.profileName==='string'?s.profileName.trim().slice(0,100):'',studentNumber:typeof s?.studentNumber==='string'?s.studentNumber.trim().slice(0,30):'',profileCreatedAt:typeof s?.profileCreatedAt==='string'&&Number.isFinite(Date.parse(s.profileCreatedAt))?s.profileCreatedAt:null,legacyProfile:s?.legacyProfile===true,examNames:names,calendarColors:colors,englishEnabled:s?.englishEnabled!==false,profilePhoto:typeof s?.profilePhoto==='string'&&s.profilePhoto.length<=100000&&/^data:image\/(?:jpeg|png|webp);base64,[A-Za-z0-9+/]+={0,2}$/.test(s.profilePhoto)?s.profilePhoto:'',budget:Math.min(480,Math.max(30,Number(s?.budget)||180)),theme:s?.theme==='amoled'?'amoled':'light',accent:/^#[0-9a-f]{6}$/i.test(s?.accent||'')?s.accent:'#2f6c52',catchup:s?.catchup!==false,start:/^\d{2}:\d{2}$/.test(s?.start||'')?s.start:'17:00',end:/^\d{2}:\d{2}$/.test(s?.end||'')?s.end:'23:00'}}
settings=cleanSettings(settings);
function bundle(){return {app:'alfaisal-review-studio',version:2,records:state,settings,extras:StudyVault.snapshot()}}
function confidenceBadge(x){let n=+rec(x).confidence||0;return `<span class="confidence ${n>=4?'green':n===3?'yellow':n?'red':'gray'}">${n>=4?'Mastered':n===3?'Needs review':n?'Struggling':'Unrated'}</span>`}
function weak(x){let r=rec(x),m=Study.mcq(r);return Study.hard(r)||(m.accuracy!==null&&m.accuracy<70)||!!r.notes}
function filtered(){let status=filters.status;if(status==='weak')filters.status='all';let a=baseFiltered();filters.status=status;return status==='weak'?a.filter(weak).sort((a,b)=>(Study.mcq(rec(a)).accuracy??101)-(Study.mcq(rec(b)).accuracy??101)):a}
function spacing(x){let s=Study.suggestions(x,rec(x),today()),a=Object.entries(s.dates),changed=a.some(([p,d])=>dates(x)[p]!==d);if(!a.length)return s.message?`<div class="spacing"><strong>Spacing check</strong><small>${esc(s.message)}</small></div>`:'';return `<div class="spacing"><strong>✦ Suggested spacing</strong><span>${a.map(([p,d])=>'R'+(+p+1)+' · '+fmt(d)).join(' &nbsp; → &nbsp; ')}</span><small>${esc(s.message)} Original preset dates stay available.</small>${changed?`<button data-spacing="${x.id}">Apply suggestion</button>`:'<span class="pill">Already in your plan</span>'}</div>`}
function row(x){const r=rec(x),m=Study.mcq(r),minutes=Math.round((r.sessions||[]).reduce((s,x)=>s+x.seconds,0)/60),links=(r.resources||[]).map((u,i)=>`<a href="${esc(u)}" target="_blank" rel="noopener noreferrer">Material ${i+1} ↗</a>`).join('');return baseRow(x)+`<div class="lecture-tools">${confidenceBadge(x)}${r.difficult?'<span class="pill mol">Difficult</span>':''}<span class="mcq-summary">${m.total?m.accuracy+'% · '+m.correct+'/'+m.total+' MCQs (last 5 sets)':'No MCQ results'}</span><button data-mcq="${x.id}">＋ Log MCQs</button><button data-timer="${x.id}">◷ Study${minutes?' · '+minutes+' min':''}</button>${links}</div>${spacing(x)}`}
function readinessCard(course){const r=Study.readiness(DATA.items,state,day,course);return `<section class="readiness-card"><div class="section-head"><strong>${course} ${course==='MOL'?'114':'112'}</strong><span class="pill">READINESS ESTIMATE</span></div><div class="readiness-number">${r.score}<small>/ 100</small></div><div class="bar ${course==='MOL'?'mol':''}"><i style="width:${r.score}%"></i></div><p>${r.scope}</p><small>${r.confidenceCount}/${r.lectures} confidence ratings · ${r.mcqCount}/${r.lectures} topics with MCQs</small></section>`}
function summaryStats(){let m=tasks(DATA.items.filter(x=>x.midterm)),c=tasks(DATA.items.filter(x=>x.course==='CVP')),p=Study.daily(DATA.items,state,day,settings,DATA.events);return `<div class="stats command-stats"><div class="stat"><div class="eyebrow">MOL 114</div><div class="value">${m.filter(t=>t.done).length} <span>/ 39</span></div><small>Midterm review passes</small></div><div class="stat"><div class="eyebrow">CVP 112</div><div class="value">${c.filter(t=>t.done).length} <span>/ 153</span></div><small>Planned review passes</small></div><div class="stat"><div class="eyebrow">YOUR DAILY PLAN</div><div class="value">${p.used} <span>min</span></div><small>${p.selected.length} tasks next · ${p.spent} min studied</small></div><div class="stat"><div class="eyebrow">WEAK TOPICS</div><div class="value">${DATA.items.filter(weak).length}</div><small>Confidence, MCQ results & notes</small></div></div>`}
function checklist(t){const x=t.x,r=rec(x),m=Study.mcq(r);return `<article class="checklist-item"><div class="checklist-top">${t.p!==null?`<label><input type="checkbox" data-id="${x.id}" data-pass="${t.p}" aria-label="${esc(x.code)} review ${t.p+1} completed"><span><strong>${esc(title(x))}</strong><small>${x.course==='CVP'?'CVP ':''}${esc(x.code)} · Review ${t.p+1} · ${t.start}–${t.end} · ${t.minutes} min</small></span></label>`:`<div><strong>${esc(title(x))}</strong><small>${esc(x.code)} · Targeted practice · ${t.start}–${t.end} · ${t.start}–${t.end} · ${t.minutes} min</small></div>`}<button data-timer="${x.id}" title="Start study timer">◷</button></div><div class="task-reason">${esc(t.reason)}</div><div class="task-actions">${confidenceBadge(x)}<button data-mcq="${x.id}">Log MCQs${m.accuracy!==null?' · '+m.accuracy+'%':''}</button><button data-edit="${x.id}">Notes & dates ↗</button></div></article>`}
function heatmap(){let last=Array.from({length:7},(_,i)=>add(day,i-6));return `<section class="panel"><div class="section-head"><h2>Study consistency</h2><span class="muted">Last 7 days</span></div><div class="heatmap">${last.map(d=>{let reviews=tasks().filter(t=>t.done&&Study.localDate(t.done)===d).length,mcqs=DATA.items.reduce((n,x)=>n+(rec(x).mcqs||[]).filter(q=>q.date===d).length,0),seconds=DATA.items.reduce((n,x)=>n+(rec(x).sessions||[]).filter(t=>Study.localDate(t.endedAt)===d).reduce((s,t)=>s+t.seconds,0),0),activity=reviews+mcqs+(seconds>0?1:0);return `<div><div class="heat ${activity>=5?'level3':activity>=2?'level2':activity?'level1':''}" title="${fmt(d)}: ${reviews} passes, ${mcqs} MCQ sets, ${Math.round(seconds/60)} study minutes">${activity||'·'}</div><small>${fmt(d)}</small></div>`}).join('')}</div><p class="section-sub" style="margin-top:12px">Activity = completed passes + logged MCQ sets + a timed-study day.</p></section>`}
function classList(d){let ev=DATA.events.filter(e=>e.date===d);return ev.length?ev.map(e=>`<div class="event"><strong>${esc(e.title)}</strong><p>${e.slot?'Source slot: '+esc(e.slot):esc(e.detail||'Date documented; time not supplied')}</p><small>${esc(e.type)}${e.cell?' · '+e.cell:''}</small></div>`).join(''):'<p class="muted">No course events documented for this date.</p>'}
function planControls(){return `<div class="plan-controls"><label>Study time available <select id="budget">${[30,60,90,120,180,240,300,360,480].map(n=>`<option value="${n}" ${settings.budget===n?'selected':''}>${n} minutes</option>`).join('')}</select></label><label class="window-label"><span>Study window</span><input id="windowStart" type="time" aria-label="Study window start" value="${esc(settings.start)}"> to <input id="windowEnd" type="time" aria-label="Study window end" value="${esc(settings.end)}"></label><label class="switch-label"><input type="checkbox" id="catchup" ${settings.catchup?'checked':''}> Catch-up outlook</label></div><p class="section-sub">Personal study window; printed class slots are automatically reserved. Times below are suggested study appointments. Estimates include 5-minute breaks. Finished review estimates or logged timer minutes (whichever is greater) use part of the daily budget.</p>`}
function scoreExplanation(){return `<details class="score-explanation"><summary>How readiness is estimated</summary><p>Equal weight per lecture: 40% completed passes + 20% confidence (1 → 0%, 5 → 100%) + 40% practice accuracy from the last five sets. Missing confidence or MCQs contributes no evidence to that component. This is a study-priority estimate, not a predicted grade or an official exam blueprint. Low MCQ sample sizes can be misleading. MOL uses lectures 1–13 through October 29, then all numbered entries.</p></details>`}
function nextAssessment(events, date){if(typeof AssessmentPlan!=='undefined'){const c=assessmentClock();return AssessmentPlan.upcoming(AssessmentPlan.catalog(events,DATA.items),date,c.date===date?c.minute:0).sort((a,b)=>a.date.localeCompare(b.date)||a.endMinute-b.endMinute)[0]||null}return events.filter(e=>e.date>=date&&/^(?:MOL\s*(?:114\s*)?(?:mid\s*term|tbl|final(?:\s*exam)?)|(?:CVP\s*112\s*)?(?:tbl[-\s]*\d+|final\s*exam|ospe))/i.test(e.title.replace(/\s+/g,' ').trim())).sort((a,b)=>a.date.localeCompare(b.date)||Number(!!b.detail)-Number(!!a.detail))[0]||null}
function assessmentHero(){const now=day,event=nextAssessment(DATA.events,now);if(!event)return `<section class="hero command-hero"><div><div class="section-head"><h2>Upcoming assessments</h2></div><p>No upcoming TBLs or exams in the supplied schedule.</p><button data-view="calendar">View schedule ↗</button></div></section>`;const n=Study.gap(event.date,now),title=event.title.replace(/\s+/g,' ').trim(),label=/^TBL/i.test(title)&&/CVP/i.test(event.source||'')?'CVP 112 · '+title:title,details=event.detail?' · '+event.detail.replace(/\s*·\s*\d{2}:\d{2}.*$/,''):'';return `<section class="hero command-hero"><div><div class="section-head"><h2>${esc(label)}</h2><span class="pill">UP NEXT · PLANNING DAY</span></div><div class="hero-days">${n===0?'Today':n+' '+(n===1?'day':'days')+' left'}</div><p>${esc(fullDate(event.date)+details)}</p><button data-view="calendar" data-day="${esc(event.date)}">View schedule ↗</button></div><div class="hero-side"><span>FOCUS FOR TODAY</span><p>Recall the gaps.<br>Test your understanding.<br>Keep CVP moving.</p><small>All tasks reflect your saved progress.</small></div></section>`}
function dashboard(){let p=Study.daily(DATA.items,state,day,settings,DATA.events),pending=DATA.items.filter(x=>spacing(x));return intro('M1-A • GROUP 1.6','Study Command Center',fullDate(day))+`${assessmentHero()}`+summaryStats()+`<div class="readiness-grid">${readinessCard('MOL')}${readinessCard('CVP')}</div>${scoreExplanation()}${examRisk()}<div class="grid"><div><section class="panel"><div class="section-head"><h2>Today's review checklist</h2><button class="linkbtn" data-view="planner">Full daily plan ↗</button></div>${planControls()}${p.selected.length?p.selected.map(checklist).join(''):'<div class="empty">No unfinished reviews due. Open All lectures to choose a topic or change the planning day.</div>'}<p class="notice">${p.deferred.length} eligible tasks deferred beyond this budget. Deferral does not mean completion or change any preset dates.</p></section>${pending.length?`<section class="panel"><h2>Spacing suggestions</h2><p class="muted">Based on actual review completion, confidence and MCQ performance.</p>${pending.slice(0,5).map(spacing).join('')}${pending.length>5?'<button data-view="lectures">See all suggestions</button>':''}</section>`:''}${heatmap()}</div><div class="right-column"><section class="panel"><div class="section-head"><h2>Your progress</h2><button class="linkbtn" data-cvp>CVP plan ↗</button></div>${progress('MOL')}${progress('CVP')}</section><section class="panel"><h2>Group 1.6 · ${fmt(day)}</h2>${classList(day)}<p class="notice">Suggested study appointments avoid the printed class slots. Merged session durations and new attendance times are not inferred; extend your reservations if a class runs longer.</p></section><section class="panel"><h2>Next best action</h2><p class="muted">${p.selected.length?esc(p.selected[0].x.code)+' · '+esc(p.selected[0].reason):'Check your weak topics or plan tomorrow.'}</p><button class="primary" ${p.selected.length?'data-timer="'+p.selected[0].x.id+'"':'data-view="weakness"'}>${p.selected.length?'Start a study session':'Open weak topics'}</button></section></div></div>`}
function planner(){const p=Study.daily(DATA.items,state,day,settings,DATA.events),outlook=Study.catchup(DATA.items,state,day,settings,DATA.events);return intro('A REALISTIC PLAN, WITH ROOM TO ADJUST','Your next study steps',fullDate(day))+`<section class="panel">${planControls()}<div class="plan-summary"><strong>${p.used} / ${p.capacity} minutes allocated</strong><span>${p.slotMinutes} min free of documented class slots · ${p.spent} min already studied · ${p.remaining} min free · ${p.deferred.length} tasks deferred</span></div><p class="notice">Priority combines exam coverage, overdue days, confidence, difficulty and recent MCQs. Before October 29, MOL 1–13 comes first, with one CVP task reserved when the budget can fit both. One unfinished pass per lecture is planned each day.</p></section><div class="grid"><section class="panel"><h2>Today's ordered plan</h2>${examRisk()}${p.selected.map((t,i)=>(i?'<div class="study-break">5 min · take a break</div>':'')+checklist(t)).join('')||'<div class="empty">No tasks due on this date.</div>'}</section><section class="panel"><h2>Classes & exam dates</h2>${classList(day)}<h3 style="margin-top:22px">Upcoming assessments</h3>${DATA.events.filter(e=>e.date>=day&&['MOL assessment guide','CVP PDF plan'].includes(e.type)&&/TBL|Final|Midterm|FINAL/.test(e.title)).slice(0,5).map(e=>`<p><b>${fmt(e.date)}</b><br>${esc(e.title)}<br><small>${esc(e.detail||'')}</small></p>`).join('')}</section></div>${settings.catchup?`<section class="panel"><div class="section-head"><h2>Seven-day catch-up outlook</h2><button id="applyCatchup">Apply this review schedule</button></div><p class="muted">Projection assumes you complete each day's plan and use the same budget. Missed reviews are spread across days. Applying changes personal due dates only; original CVP dates remain accessible. No checkboxes are completed.</p><div class="catchup-grid">${outlook.map(v=>`<article><strong>${fmt(v.date)}</strong><small>${v.used} min · ${v.selected.length} tasks</small>${v.selected.map(t=>`<p>${esc(t.x.code)} · ${t.p===null?'Practice':'R'+(t.p+1)}</p>`).join('')||'<p>Clear</p>'}</article>`).join('')}</div><p class="notice">${outlook.at(-1).deferred.length} tasks remain beyond the last day's budget. Exams still need preparation: increase your budget or move tasks manually if the plan cannot cover them in time.</p></section>`:''}<section class="panel"><h2>Deferred from today</h2>${p.deferred.length?p.deferred.map(t=>`<div class="deferred"><span>${esc(t.x.code)} · ${esc(title(t.x))}</span><small>${t.minutes} min · ${esc(t.reason)}</small></div>`).join(''):'<p class="muted">Everything eligible fits your budget.</p>'}</section>`}
let mcqLecture=null;
function openMcq(id){mcqLecture=DATA.items.find(x=>x.id===id);$('#mcqTitle').textContent='Log MCQs · '+mcqLecture.code;$('#mcqTotal').value='';$('#mcqCorrect').value='';$('#mcqDate').value=today();$('#mcqSource').value='';$('#mcqHistory').innerHTML='<h3 style="margin-top:24px">Practice history</h3>'+((rec(mcqLecture).mcqs||[]).slice().reverse().map(q=>`<div class="mcq-record"><span>${fmt(q.date)} · <b>${q.correct}/${q.total}</b> (${Math.round(q.correct/q.total*100)}%)<small>${esc(q.source||'Practice')}</small></span><button type="button" data-delete-mcq="${esc(q.id)}">Remove</button></div>`).join('')||'<p class="muted">No practice recorded yet.</p>');$('#mcqDialog').showModal()}
function logMcq(id,correct,total,date,source){const x=DATA.items.find(x=>x.id===id);if(!x||!Number.isInteger(correct)||!Number.isInteger(total)||total<1||total>10000||correct<0||correct>total)throw Error('Correct answers must be between 0 and the attempted total.');if(correct*100<total*15)return false;state[id]={...rec(x),mcqs:[...(rec(x).mcqs||[]),{id:crypto.randomUUID(),correct,total,date,source,createdAt:new Date().toISOString()}]};persist();return true}
function openEdit(id){baseOpenEdit(id);$('#difficult').checked=!!rec(editing).difficult;$('#resources').value=(rec(editing).resources||[]).join('\n');$('#spacingEditor').innerHTML=spacing(editing)}
function practice(){const rows=DATA.items.map(x=>({x,m:Study.mcq(rec(x))})).filter(v=>v.m.total).sort((a,b)=>a.m.accuracy-b.m.accuracy),totals=rows.reduce((o,v)=>({correct:o.correct+v.m.correct,total:o.total+v.m.total}),{correct:0,total:0});return intro('TURN PRACTICE INTO YOUR NEXT PRIORITY','Practice & MCQ performance','Log real results by lecture. Low scores feed your planner and earlier spacing suggestions.')+`<div class="stats"><div class="stat"><div class="eyebrow">ACCURACY</div><div class="value">${totals.total?Math.round(totals.correct/totals.total*100)+'%':'—'}</div><small>Last 5 sets per lecture</small></div><div class="stat"><div class="eyebrow">QUESTIONS LOGGED</div><div class="value">${totals.total}</div><small>${totals.correct} correct in recent sets</small></div><div class="stat"><div class="eyebrow">TOPICS PRACTICED</div><div class="value">${rows.length} / 79</div><small>Question counts affect sample reliability</small></div><div class="stat"><div class="eyebrow">BELOW 70%</div><div class="value">${rows.filter(v=>v.m.accuracy<70).length}</div><small>Prioritized as weak topics</small></div></div><section class="panel"><div class="section-head"><h2>Log a practice session</h2></div><div class="filters"><select id="practiceLecture" aria-label="Lecture to log MCQs">${DATA.items.map(x=>`<option value="${x.id}">${x.course==='CVP'?'CVP ':''}${esc(x.code)} · ${esc(title(x))}</option>`).join('')}</select><button id="practiceLog" class="primary">＋ Enter results</button></div></section><section class="panel"><h2>Performance by lecture · weakest first</h2>${rows.length?rows.map(({x,m})=>`<article class="performance-row"><div><b>${esc(x.code)} · ${esc(title(x))}</b><small>${m.correct}/${m.total} recent questions · ${m.sessions} sets recorded</small></div><div class="accuracy ${m.accuracy<60?'red':m.accuracy<80?'yellow':'green'}">${m.accuracy}%</div><button data-mcq="${x.id}">Add / history</button><button data-edit="${x.id}">Notes</button></article>`).join(''):'<div class="empty">No MCQ results yet. Add your first practice set above.</div>'}</section><section class="panel"><h2>Import an explained question set</h2><p class="muted">Practice your own set together on one page. Results update each lecture’s MCQ history.</p><button id="importQuestions">↑ Import question set</button><button id="questionTemplate">↓ Download JSON template</button><input id="questionsFile" type="file" accept=".json,application/json" hidden><div id="quizArea">${quizMarkup()}</div></section>`}
let quiz=null;
function quizMarkup(){if(!quiz)return '<p class="section-sub" style="margin-top:15px">Import JSON with explained questions, lecture IDs and a reason for every option. Your imported set stays on this device.</p>';return typeof importedSetMarkup==='function'?importedSetMarkup():'<p>Preparing question set…</p>'}
function validateQuestions(o){if(!Array.isArray(o?.questions)||!o.questions.length||o.questions.length>200)throw Error('Supply 1–200 questions.');return o.questions.map(q=>{if(!DATA.items.some(x=>x.id===q.lectureId)||typeof q.question!=='string'||!q.question.trim()||q.question.length>4000||!Array.isArray(q.options)||q.options.length<2||q.options.length>6||q.options.some(v=>typeof v!=='string'||!v.trim()||v.length>2000)||!Number.isInteger(q.answer)||q.answer<0||q.answer>=q.options.length)throw Error('Invalid question, options, answer index or lectureId.');if(typeof q.explanation!=='string'||!q.explanation.trim()||!Array.isArray(q.reasons)||q.reasons.length!==q.options.length||q.reasons.some(r=>typeof r!=='string'||!r.trim()))throw Error('Every imported question needs an explanation and one reason per option.');return {lectureId:q.lectureId,question:q.question,options:q.options,answer:q.answer,explanation:q.explanation.slice(0,4000),reasons:q.reasons.map(r=>r.slice(0,4000))}})}
let timer=null;try{timer=JSON.parse(localStorage.getItem(KEY+'-timer')||'null')}catch{}
function timerElapsedMs(t=timer,now=Date.now()){if(!t)return 0;const saved=Number.isFinite(t.accumulatedMs)?Math.max(0,t.accumulatedMs):0;return saved+(t.paused?0:Math.max(0,now-(t.resumedAt??t.started)))}
function studyTimerIcon(name){const paths={finish:'M5 12l4 4L19 6',pause:'M8 5v14 M16 5v14',resume:'M8 5l11 7-11 7Z',discard:'M6 6l12 12 M18 6 6 18'};return `<svg viewBox="0 0 24 24" width="21" height="21" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]}"/></svg>`}
function timerPaint(){const el=$('#timerBar');el.hidden=!timer;if(!timer){delete el.dataset.timerSignature;return}const x=DATA.items.find(x=>x.id===timer.id);if(!x){timer=null;el.hidden=true;delete el.dataset.timerSignature;return}const seconds=Math.floor(timerElapsedMs()/1000),signature=timer.id+':'+!!timer.paused;if(el.dataset.timerSignature!==signature){el.dataset.timerSignature=signature;el.innerHTML=`<span><b>${esc(x.code)}</b> · Study timer${timer.paused?' · Paused':''}</span><strong id="studyElapsed" role="timer" aria-label="Active study time"></strong><div class="study-timer-actions"><button id="stopTimer" aria-label="Finish and save study time" title="Finish and save study time">${studyTimerIcon('finish')}</button><button id="pauseTimer" aria-label="${timer.paused?'Resume':'Pause'} study timer" title="${timer.paused?'Resume':'Pause'} study timer" aria-pressed="${!!timer.paused}">${studyTimerIcon(timer.paused?'resume':'pause')}</button><button id="cancelTimer" aria-label="Discard study timer" title="Discard study timer">${studyTimerIcon('discard')}</button></div>`}$('#studyElapsed').textContent=String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0')}
function toggleStudyTimer(){if(!timer)return;if(timer.paused){timer.paused=false;timer.resumedAt=Date.now()}else{timer.accumulatedMs=timerElapsedMs();timer.paused=true;timer.resumedAt=null}timerSave();timerPaint()}

function timerSave(){try{localStorage.setItem(KEY+'-timer',JSON.stringify(timer))}catch{}}
function finishTimer(){if(!timer)return;let x=DATA.items.find(x=>x.id===timer.id),seconds=Math.floor(timerElapsedMs()/1000);if(seconds>8*3600){toast('Session exceeds 8 hours. Discard it and start a fresh timer.');return}if(seconds>=1){state[x.id]={...rec(x),sessions:[...(rec(x).sessions||[]),{startedAt:new Date(timer.started).toISOString(),endedAt:new Date().toISOString(),seconds}]};persist()}timer=null;timerSave();timerPaint();render();toast('Study time saved. Review completion stays separate.')}
function applySpacing(id){let x=DATA.items.find(x=>x.id===id),s=Study.suggestions(x,rec(x),today()),d=[...dates(x)];for(let [p,v] of Object.entries(s.dates))if(!done(x,+p))d[p]=v;state[id]={...rec(x),dates:d};persist();render();if(editing?.id===id&&$('#editor').open)openEditFields();toast('Suggested dates applied. Original dates preserved.')}
function openEditFields(){[0,1,2].forEach(p=>$('#date'+p).value=dates(editing)[p]);$('#spacingEditor').innerHTML=spacing(editing)}
function validateExtras(r,c){if(r.learning!==undefined){if(typeof Learn!=='undefined')c.learning=Learn.validate(r.learning);else c.learning=r.learning;}if(r.difficult!==undefined){if(typeof r.difficult!=='boolean')throw Error('Invalid difficulty.');c.difficult=r.difficult}if(r.resources!==undefined){if(!Array.isArray(r.resources)||r.resources.length>30||r.resources.some(u=>typeof u!=='string'||u.length>3000||!/^https?:\/\//i.test(u)))throw Error('Invalid material links.');c.resources=r.resources}if(r.mcqs!==undefined){if(!Array.isArray(r.mcqs)||r.mcqs.length>5000)throw Error('Too many MCQ sessions.');c.mcqs=r.mcqs.map(q=>{if(typeof q.id!=='string'||!Number.isInteger(q.total)||q.total<1||q.total>10000||!Number.isInteger(q.correct)||q.correct<0||q.correct>q.total||!validDate(q.date)||!validStamp(q.createdAt)||typeof q.source!=='string'||q.source.length>200)throw Error('Invalid MCQ session.');return {id:q.id,correct:q.correct,total:q.total,date:q.date,source:q.source,createdAt:q.createdAt}})}if(r.sessions!==undefined){if(!Array.isArray(r.sessions)||r.sessions.length>5000)throw Error('Too many study sessions.');c.sessions=r.sessions.map(t=>{if(!validStamp(t.startedAt)||!validStamp(t.endedAt)||!Number.isInteger(t.seconds)||t.seconds<0||t.seconds>8*3600)throw Error('Invalid timer session.');return {startedAt:t.startedAt,endedAt:t.endedAt,seconds:t.seconds}})}}
function validDate(v){return typeof v==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(v)&&Number.isFinite(Date.parse(v))&&new Date(v).toISOString().slice(0,10)===v}
function validStamp(v){return typeof v==='string'&&Number.isFinite(Date.parse(v))}
let deltaBaseline=null,deltaRevision=null,deltaSupported=false;
let syncMeta={revision:null,dirty:Object.keys(state).length>0},syncTimer=null,syncBusy=false,syncConflict=null,changeNumber=0,syncQueued=false,syncRetryAt=0,syncFailures=0;
try{syncMeta={...syncMeta,...JSON.parse(localStorage.getItem(KEY+'-sync')||'{}')}}catch{}
function saveSyncMeta(){try{localStorage.setItem(KEY+'-sync',JSON.stringify(syncMeta))}catch{}}
function syncMessage(s){$('#syncState').textContent=s;$('#syncSignIn').hidden=!/sign in/i.test(s);$('#saveLabel').textContent=storageOK?'Saved on this device':'Device saving unavailable';if(typeof paintSyncSummary==='function')paintSyncSummary(s)}
function scheduleSync(){syncMeta.dirty=true;changeNumber++;saveSyncMeta();clearTimeout(syncTimer);syncMessage('Changes saved here · waiting to sync');syncTimer=setTimeout(()=>syncCloud(),300)}
function showConflict(remote){syncConflict=remote;$('#syncConflict').hidden=true;syncMessage('Reconciling newest changes…');if(typeof resolveAutoConflict==='function')resolveAutoConflict(remote)}
function storeLocalOnly(){try{localStorage.setItem(KEY,JSON.stringify({version:2,records:state,settings}));storageOK=true}catch{storageOK=false;$('#storageStatus').textContent='Device storage is unavailable. Export a backup.';if(typeof paintSyncSummary==='function')paintSyncSummary('Device saving unavailable')}}
function adoptCloud(remote){state=validateBackup(remote.snapshot);settings=cleanSettings(remote.snapshot.settings);if(typeof StudentProfile!=='undefined')StudentProfile.restoreLegacy(remote.snapshot);StudyVault.apply(remote.snapshot.extras);syncMeta={revision:remote.revision,dirty:false};saveSyncMeta();storeLocalOnly();syncConflict=null;$('#syncConflict').hidden=true;render();syncMessage('Cloud saved · '+(remote.updatedAt?stamp(remote.updatedAt):'up to date'))}
function vaultValuesEqual(a,b){const clean=x=>Object.fromEntries(Object.entries(x?.stores||{}).map(([k,v])=>[k,v.value]).sort(([a],[b])=>a.localeCompare(b)));return syncValuesEqual(clean(a),clean(b))}
function syncValuesEqual(a,b){const canonical=v=>Array.isArray(v)?v.map(canonical):v&&typeof v==='object'?Object.fromEntries(Object.keys(v).sort().map(k=>[k,canonical(v[k])])):v;return JSON.stringify(canonical(a))===JSON.stringify(canonical(b))}
async function syncFetch(url,options={}){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),15000);try{return await fetch(url,{...options,signal:controller.signal})}finally{clearTimeout(timer)}}
async function syncCloud(force=false){if(document.documentElement?.dataset.boot==='loading'){syncQueued=true;return}if(syncBusy){syncQueued=true;return}if(syncConflict||!force&&Date.now()<syncRetryAt)return;if($('#editor').open||$('#mcqDialog').open||typeof queueEditor!=='undefined'&&queueEditor){syncMessage('Save or close the editor to sync');return}if(!/^https?:$/.test(location.protocol)){syncMessage('Offline copy · use Export / Import to transfer progress');return}syncBusy=true;syncMessage('Syncing privately…');try{const known=Number.isSafeInteger(syncMeta.revision)&&syncMeta.revision>=0&&(typeof StudentProfile==='undefined'||StudentProfile.accountBound)?'?since='+syncMeta.revision:'';const response=await syncFetch('/api/progress'+known,{cache:'no-store',credentials:'same-origin'});if(response.status===401&&typeof StudentProfile!=='undefined')StudentProfile.signedOut();if(!response.ok)throw Error(response.status===401?'Sign in on the published website to sync.':'Cloud unavailable · device copy retained.');const remote=await response.json();if(typeof StudentProfile!=='undefined'&&!await StudentProfile.remote(remote))return;deltaSupported=remote.acceptsPatch===true;if(remote.snapshot){deltaBaseline=structuredClone(remote.snapshot);deltaRevision=remote.revision}syncFailures=0;syncRetryAt=0;if(remote.unchanged&&!syncMeta.dirty){syncMessage('Cloud saved · up to date');return}if(remote.snapshot)validateBackup(remote.snapshot);if(remote.snapshot&&syncValuesEqual(remote.snapshot.records,state)&&syncValuesEqual(cleanSettings(remote.snapshot.settings),settings)&&vaultValuesEqual(remote.snapshot.extras,StudyVault.snapshot())){syncMeta={revision:remote.revision,dirty:false};saveSyncMeta();syncMessage('Cloud saved · up to date');return}
if(!syncMeta.dirty&&remote.snapshot){adoptCloud(remote);return}if(remote.snapshot&&remote.revision!==syncMeta.revision){if(!Object.keys(state).length&&!syncMeta.dirty){adoptCloud(remote);return}showConflict(remote);return}
if(!remote.snapshot&&!Object.keys(state).length&&!syncMeta.dirty){syncMeta.revision=0;saveSyncMeta();syncMessage('Cloud ready · start your first review');return}
const generation=changeNumber,payload=structuredClone(bundle()),fullBody=JSON.stringify({revision:remote.revision,snapshot:payload});let method='PUT',body=fullBody;if(deltaSupported&&deltaBaseline&&deltaRevision===remote.revision&&typeof ProgressDelta!=='undefined'){const patch=ProgressDelta.diff(deltaBaseline,payload),candidate=JSON.stringify({revision:remote.revision,patch});if(patch.length<=8000&&candidate.length<fullBody.length*.8){method='PATCH';body=candidate}}let put=await syncFetch('/api/progress',{method,credentials:'same-origin',headers:{'Content-Type':'application/json'},body});if(method==='PATCH'&&[400,404,405].includes(put.status)){deltaSupported=false;put=await syncFetch('/api/progress',{method:'PUT',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:fullBody})}if(put.status===409){syncBusy=false;await syncCloud();return}if(!put.ok){let msg=put.status===401?'Sign in again to sync.':put.status===413?'Progress is too large to sync. Export a backup.':put.status===400?'Some saved progress could not be accepted. Export a backup.':'Cloud save failed · device copy retained.';throw Error(msg)}const result=await put.json();deltaBaseline=structuredClone(payload);deltaRevision=result.revision;syncMeta.revision=result.revision;syncMeta.dirty=generation!==changeNumber;saveSyncMeta();syncMessage(syncMeta.dirty?'New changes waiting to sync':'Cloud saved · '+stamp(result.updatedAt));if(syncMeta.dirty)syncTimer=setTimeout(()=>syncCloud(),300)
}catch(err){syncFailures++;syncRetryAt=Date.now()+Math.min(60000,5000*2**Math.min(syncFailures-1,4));syncMessage(err.name==='AbortError'?'Sync timed out · device copy retained.':err.message||'Cloud unavailable · device copy retained.')}finally{syncBusy=false;if(syncQueued){syncQueued=false;clearTimeout(syncTimer);syncTimer=setTimeout(()=>syncCloud(),Math.max(300,syncRetryAt-Date.now()))}}}
$('#syncNow').onclick=()=>syncCloud(true);$('#useCloud').onclick=()=>{if(syncConflict&&confirm('Use cloud progress on this device? Export this device’s backup first if you need to keep it.'))adoptCloud(syncConflict)};$('#keepLocal').onclick=()=>{if(!syncConflict||!confirm('Replace cloud progress with this device’s copy? Other devices will receive this copy on their next sync.'))return;syncMeta={revision:syncConflict.revision,dirty:true};syncConflict=null;$('#syncConflict').hidden=true;saveSyncMeta();syncCloud()};
$('#closeMcq').onclick=()=>{$('#mcqDialog').close();syncCloud()};$('#mcqForm').onsubmit=e=>{e.preventDefault();try{let d=$('#mcqDate').value;if(!validDate(d)||d>today())throw Error('Choose today or a previous practice date.');const saved=logMcq(mcqLecture.id,Number($('#mcqCorrect').value),Number($('#mcqTotal').value),d,$('#mcqSource').value.trim());$('#mcqDialog').close();render();toast(saved?'MCQ results saved. Priorities and spacing updated.':'Below 15% · this result was not saved.')}catch(err){alert(err.message)}};
$('#editform').onsubmit=e=>{e.preventDefault();const final=editing.course==='CVP'?AssessmentPlan.cvpFinalDate(DATA.events):null;if(final&&[0,1,2].some(p=>!done(editing,p)&&$('#date'+p).value!==dates(editing)[p]&&$('#date'+p).value>=final)){toast('Schedule CVP reviews before the final on '+fullDate(final));return;}let urls=$('#resources').value.split('\n').map(v=>v.trim()).filter(Boolean);if(urls.length>30||urls.some(u=>!/^https?:\/\//i.test(u)||u.length>3000)){alert('Use up to 30 complete http or https resource links, one per line.');return}state[editing.id]={...rec(editing),title:$('#titleInput').value.trim()||editing.title,dates:[0,1,2].map(p=>$('#date'+p).value),confidence:+$('#confidence').value,notes:$('#notes').value,difficult:$('#difficult').checked,resources:urls};persist();$('#editor').close();render();toast('Lecture saved. Planner and spacing updated.')};
document.addEventListener('change',async e=>{let t=e.target;if(t.id==='budget'){settings.budget=Number(t.value);persist();render()}if(t.id==='windowStart'||t.id==='windowEnd'){let start=t.id==='windowStart'?t.value:settings.start,end=t.id==='windowEnd'?t.value:settings.end;if(start>=end){toast('Study end must be later than start.');render();return}settings.start=start;settings.end=end;persist();render()}if(t.id==='catchup'){settings.catchup=t.checked;persist();render()}if(t.id==='questionsFile'){try{let f=t.files[0];if(!f)return;if(f.size>2000000)throw Error('Question set exceeds 2 MB.');quiz={questions:validateQuestions(JSON.parse(await f.text())),index:0,answers:[],finished:false,correct:0};$('#quizArea').innerHTML=quizMarkup();toast('Question set imported · ready to practice')}catch(err){alert(err.message)}finally{t.value=''}}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.mcq)openMcq(b.dataset.mcq);if(b.dataset.spacing)applySpacing(b.dataset.spacing);if(b.dataset.timer){if(timer){toast('Finish or discard the current session first.');return}timer={id:b.dataset.timer,started:Date.now()};timerSave();timerPaint();toast('Timer started · finish it to log study time')}if(b.id==='stopTimer')finishTimer();if(b.id==='pauseTimer')toggleStudyTimer();if(b.id==='cancelTimer'){timer=null;timerSave();timerPaint();toast('Timer discarded')}if(b.dataset.deleteMcq){let x=mcqLecture;state[x.id]={...rec(x),mcqs:(rec(x).mcqs||[]).filter(q=>q.id!==b.dataset.deleteMcq)};persist();openMcqHistory();render();toast('MCQ result removed')}if(b.id==='practiceLog')openMcq($('#practiceLecture').value);if(b.id==='importQuestions')$('#questionsFile').click();if(b.id==='questionTemplate'){const example={questions:[{lectureId:'MOL-1',question:'Replace this with your own verified practice question.',options:['Replace option A','Replace option B'],answer:0,explanation:'Add a verified explanation here.',reasons:['Explain why A is correct.','Explain why B is incorrect.']}]};downloadJSON(example,'question-set-template.json')}if(b.id==='nextQuestion'){const answer=document.querySelector('input[name="quizAnswer"]:checked');if(!answer){toast('Choose an answer first.');return}quiz.answers[quiz.index]=Number(answer.value);if(quiz.index<quiz.questions.length-1)quiz.index++;else{quiz.finished=true;quiz.correct=quiz.questions.reduce((n,q,i)=>n+(quiz.answers[i]===q.answer?1:0),0);let sets={};quiz.questions.forEach((q,i)=>{sets[q.lectureId]??={total:0,correct:0};sets[q.lectureId].total++;if(quiz.answers[i]===q.answer)sets[q.lectureId].correct++});for(const [id,q] of Object.entries(sets))logMcq(id,q.correct,q.total,today(),'Imported practice question set');render();toast('Practice results saved by lecture.')}if($('#quizArea'))$('#quizArea').innerHTML=quizMarkup()}if(b.id==='clearQuiz'){quiz=null;$('#quizArea').innerHTML=quizMarkup()}if(b.id==='applyCatchup'){let outlook=Study.catchup(DATA.items,state,day,settings,DATA.events);for(const v of outlook)for(const t of v.selected){if(t.p===null||done(t.x,t.p))continue;let d=[...dates(t.x)];d[t.p]=v.date;state[t.x.id]={...rec(t.x),dates:d}}persist();render();toast('Catch-up dates applied. No reviews marked done.')}});
function openMcqHistory(){const total=$('#mcqTotal').value,correct=$('#mcqCorrect').value;$('#mcqDialog').close();openMcq(mcqLecture.id);$('#mcqTotal').value=total;$('#mcqCorrect').value=correct}
function downloadJSON(data,name){let url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}
window.addEventListener('studio-ready',()=>{syncQueued=false;syncCloud()});window.addEventListener('online',()=>syncCloud(true));window.addEventListener('focus',()=>syncCloud());document.addEventListener('visibilitychange',()=>{if(!document.hidden)syncCloud();else if(syncMeta.dirty)syncCloud()});setInterval(()=>timerPaint(),1000);setInterval(()=>{if(!document.hidden&&navigator.onLine!==false)syncCloud()},5000);
render();timerPaint();if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>syncCloud(),{once:true});else syncCloud();

function examRisk(){if(day>'2026-10-28')return '';const remaining=tasks(DATA.items.filter(x=>x.midterm)).filter(t=>!t.done).length,projected=Study.catchup(DATA.items,state,day,settings,DATA.events).filter(v=>v.date<'2026-10-29').flatMap(v=>v.selected).filter(t=>t.x.midterm&&t.p!==null).length,uncovered=Math.max(0,remaining-projected);return uncovered?`<p class="notice exam-risk"><b>Midterm capacity check:</b> ${uncovered} of ${remaining} unfinished MOL passes do not fit before October 29 at this daily budget and spacing. Increase study time, focus on the highest-risk topics, or adjust dates manually. No plan can guarantee exam readiness.</p>`:''}
